sys_script_include.script:
var parseAttachments = Class.create();
parseAttachments.prototype = {
    initialize: function() {},


    parseExcelFile: function(sourceSysID) {


        /*excelRowArray sample structure

		[{
                "TradeRef": "R-205-3345",
                "TradeID": "HK-HSBC-212121212-2323",
                "LegacyStatus": "CONF",
                "OwningBusiness": "DCC HK"
            }, {
                "TradeRef": "D-238-2233",
                "TradeID": "AU-HSBC-212121212-2323",
                "LegacyStatus": "MATCH",
                "OwningBusiness": "DCC AU"
            }]*/


        var excelRowArray = [];
        var rejectedTrades = [];
        var headerArray = [];

        //getting the attachment
        var getAttachment = new GlideRecord('sys_attachment');
        getAttachment.addEncodedQuery('table_sys_id=' + sourceSysID);
        getAttachment.query();
        if (getAttachment.next()) {
            var attachmentRec = getAttachment.getValue('sys_id');
        }
        //getting attachment

        var attachment = new GlideSysAttachment(); //method to get the contents of the attachment
        var attachmentDetails = attachment.getContentStream(attachmentRec); //getting content of the EXcel

        var parser = new sn_impex.GlideExcelParser(); //method to parse the content of the Excel
        parser.setSource(attachmentDetails); //setting the source to parse the content from the stream

        var getSheet = parser.getSheetNames(); //getting the sheet name to fetch details
        parser.setSheetName(getSheet); //setting the sheet to parse



        //parsing all the details in sheet from above
        if (parser.parse()) { //converting into readable format using parse

            //headers
            var getHeaders = parser.getColumnHeaders();
            headerArray.push(getHeaders + '');
            //headers


            while (parser.next()) { //iterating over each row

                //pushing all the rows as object
                var getRows = parser.getRow(); //reading row by row
                var rowObj = JSON.stringify(getRows); //holds the rows of Excel as comma sepearated
                excelRowArray.push(rowObj + '');
                //pushing all the rows as object

                //{"Trade Ref":"R-205-3345","Trade ID":"HK-HSBC-212121212-2323","Legacy Status":"CONF","Owning Business":"DCC HK"} //sample row

            }



        }
        //parsing all the details in sheet from above


        //reading all the headers
        var headerFinal = [];
        var headerLength = headerArray.toString().split(",").length;

        for (var j = 0; j < headerLength; j++) {
            headerFinal.push(headerArray.toString().split(",")[j] + " " + "|");
        }
        gs.info(headerFinal.toString().replaceAll(",", " "));
        //reading all the headers


        //reading all parsed Object in excelRowArray
        for (var i = 0; i < excelRowArray.length; i++) {

            var getData = JSON.parse(excelRowArray[i]);
            gs.info('-------------------------------------------------------------------------------------------');
            gs.info(getData.TradeRef + "|" + getData.TradeID + "|" + getData.LegacyStatus + "|" + getData.OwningBusiness);


            this.createRecordsFromExcel(getData.TradeRef, getData.TradeID, getData.LegacyStatus, getData.OwningBusiness);


        }
        //reading all parsed Object in excelRowArray

    },


    createRecordsFromExcel: function(tradeRef, tradeID, legacyStatus, owningBus) {


        var createInc = new GlideRecord('sn_customerservice_case');
        createInc.initialize();
        createInc.short_description = tradeRef;
        createInc.description = tradeRef + "-" + tradeID + "-" + legacyStatus + "-" + owningBus;
        createInc.insert();

    },

    type: 'parseAttachments'
};
